zoom_min    = 1
zoom_max    = 5
language    = 'de'

img_path       = "./"              # default image path


keys        = True         # use keys to control additional to ui clicks
keytime     = 50           # key wait time in ms - changing may reduce flicker

ui_visible = True

brightness     = 0                 # standard value for brightness
contrast       = 255               # standard value for contrast
colormode      = 0                 # the actual color mode (0 color, 1 grey, 2 b/w)

blank_rgb       = [255, 255, 255]   # rgb-values for blanked screen (b key)
blanked = False # (start with) showing a curtain instead of the captured image


border = 40 # how many pixel are considered as the edge to touch-resize window
rect = None # placeholder for marking touch-ares with a grey rect
edge_move = False


map_pos     = 'UR' # where the image map is shown
map_visible = True # whether the image map is visible
map_width   = 100  # the width of the image map
map_mscreen = 50   # margin to screen edge

cmd = None    # placeholder for commands evaluated at the end of the main loop (can be triggered by mouse/ui or keys)


# common webcam resolutions to test
test_res = [(1920,1080), (1280, 720), (960, 540), (848, 480), (640, 480)]


