# mouse callback function
def mouse_event(event, x, y, flags, param):
    global map_res, zoom_res, win_res, mouse_start, mouse_delta, mouse_mode, zoom_pos, zoom_posd, zoom, edge_loc, border, reshape, reshape_start, win_delta, ui_res, new_res, cmd

    # check if mouse position within defined edges
    if x < border:
        if y < border:
            edge_loc   = 'UL'
        elif y + border > win_res[1]:
            edge_loc   = 'DL'
        else:
            edge_loc   = 'L'
    elif x + border > win_res[0]:
        if y < border:
            edge_loc   = 'UR'
        elif y + border > win_res[1]:
            edge_loc   = 'DR'
        else:
            edge_loc   = 'R'
    elif x > win_res[0] // 2 - border and x < win_res[0] // 2 + border and y > win_res[1] // 2 - border and y < win_res[1] // 2 + border:
            edge_loc   = 'M'
    else:
        if y < border:
            edge_loc   = 'U'
        elif y + border > win_res[1]:
            edge_loc = 'D'

    if event == cv2.EVENT_LBUTTONDOWN:
        mouse_start = (x, y)
        mouse_delta = (0, 0)
        #mouse_mode = ""

        # depending on the area clicked on, run different delta-variables
        if edge_loc != "": # edge/center was clicked
            mouse_mode = "edge"
        elif x<1 and y<1: # menu was clicked
            mouse_mode = "menu"
            
        elif map_visible and x in range(win_res[0]-map_mscreen-map_res[0], win_res[0]-map_mscreen) and y in range(map_mscreen, map_mscreen+map_res[1]): # click to map
            mouse_mode = "map" # move map
        elif x in range(ui_pos[0], ui_pos[0] + ui_res[0]) and y in range(ui_pos[1], ui_pos[1] + ui_res[1]): # menu was clicked
            print("Menu clicked")
        elif mouse_mode == "mark": # menu was clicked
            mouse_mode = "markpaint"
        elif mouse_mode == "ocr": # menu was clicked
            mouse_mode = "ocrpaint"
        else:
            if mouse_mode == "":
                mouse_mode = "pan"

        # ~ if (x in range(win_res[0]-50,win_res[0]) and y in range(win_res[1]-50,win_res[1])) and (not fullscreen) and (not reshape):
            # ~ reshape = True
            # ~ reshape_start = (x, y)
            # ~ win_delta = (0, 0)
    elif event == cv2.EVENT_MOUSEMOVE:
        if mouse_mode != "":
            mouse_delta = x - mouse_start[0], y - mouse_start[1]
            
        # clicked in reshape-area
        # ~ if edge_move:
            # ~ window['pos'] = (x - edge_old[0], y- edge_old[1])
            
            # ~ print(window['pos'])
            
        # ~ if reshape:
            # ~ win_delta = (x - reshape_start[0], y - reshape_start[1])

    elif event == cv2.EVENT_LBUTTONUP:
        print(mouse_mode)
        if mouse_mode == "edge": # edge/center was clicked
            mouse_mode  = ""
        elif mouse_mode == "menu": # menu was clicked
            mouse_mode  = ""
        elif mouse_mode == "map": # click to map
            # get coordinates and set new zoom_pos
            
            xn = win_res[0]/map_res[0] * (x - win_res[0] + map_mscreen  + map_res[0])
            yn = win_res[1]/map_res[1] * (y - map_mscreen)
            
            zoom_pos = int(xn), int(yn)
            
            mouse_mode  = ""
        elif mouse_mode == "pan":
            zoom_pos = zoom_posd
            mouse_mode  = ""
        elif mouse_mode == "markpaint": # new zoom area - recalculate zoom_pos / zoom_res
            mark_center = mouse_start[0] + mouse_delta[0] // 2, mouse_start[1] + mouse_delta[1] // 2
            fac = zoom_res[0] / win_res[0]
            edge = zoom_pos[0] - zoom_res[0] // 2, zoom_pos[1] - zoom_res[1] // 2
            # calculate new zoom position (by coordinate transformation)
            zoom_pos_alt = zoom_pos
            
            zoom_pos = int(mark_center[0] * fac + edge[0]), int(mark_center[1] * fac + edge[1])
            
            mark_width = mouse_delta[0] # todo - width OR height
            zoom_alt = zoom
            #zoom = win_res[0] / (mark_width * zoom_res[0] / win_res[0])
            zoom = 3*zoom
            print("alt", zoom_alt, "-> neu", zoom)
            #zoom_pos = zoom_pos[0] + int(()/zoom_factor), zoom_pos[1] + int((mouse_delta[1]-mouse_start[1] / 2)/zoom_factor)
            #print ("alter zoom", zoom_factor, "neues Verhältnis", ((mouse_delta[0]-mouse_start[0])/zoom_res[0]  ))
            #zoom = zoom/((mouse_delta[0]-mouse_start[0])/zoom_res[0]  )
            mouse_mode = ""
        elif mouse_mode == "ocrpaint":
            # do some image manupulations with the selected area...
            ocr_img = frame[mouse_start[1]:mouse_start[1]+mouse_delta[1], mouse_start[0]:mouse_start[0]+mouse_delta[0]]
            ocr_gray = cv2.cvtColor(ocr_img, cv2.COLOR_RGB2GRAY)
            ocr_gray, ocr_img_bin = cv2.threshold(ocr_gray,128,255,cv2.THRESH_BINARY | cv2.THRESH_OTSU)
            ocr_gray = cv2.bitwise_not(ocr_img_bin)
            ocr_kernel = np.ones((2, 1), np.uint8)
            ocr_img = cv2.erode(ocr_gray, ocr_kernel, iterations=1)
            ocr_img = cv2.dilate(ocr_img, ocr_kernel, iterations=1)
            # ... then use pytesseract to detect the text ...
            ocr_txt = pytesseract.image_to_string(ocr_img)
            # ... and use pyperclip to copy text to clipboard
            pyperclip.copy(ocr_txt)            
            mouse_mode = ""

        # always reset mouse delta
        
        mouse_delta = (0, 0)

        # menu buttons
        # ~ # ui and gridclick -> button
        gridx = -1
        for testx in uigrid[0]:
            if x > ui_pos[0]+testx:
                gridx += 1
        gridy = -1
        for testy in uigrid[1]:
            if y > ui_pos[1]+testy:
                gridy += 1
        if gridx+1 == len(uigrid[0]) or gridy+1 == len(uigrid[1]):
            gridclick = (-1, -1)
        else:
            gridclick = (gridx, gridy)
        
        
        if gridclick == (0,0):
            cmd = "camresminus"
        elif gridclick == (1,0):
            cmd = "camnext"
        elif gridclick == (2,0):
            cmd = "camresplus"
        elif gridclick == (0,1):
            cmd = "brightminus"
        elif gridclick == (1,1):
            cmd = "brightreset"
        elif gridclick == (2,1):
            cmd = "brightplus"
        elif gridclick == (0,2):
            cmd = "contrastminus"
        elif gridclick == (1,2):
            cmd = "contrastreset"
        elif gridclick == (2,2):
            cmd = "contrastplus"
        elif gridclick == (0,3):
            cmd = "zoomminus"
        elif gridclick == (1,3):
            cmd = "zoomreset"
        elif gridclick == (2,3):
            cmd = "zoomplus"
        elif gridclick == (0,4):
            cmd = "rotationminus"
        elif gridclick == (1,4):
            cmd = "rotationreset"
        elif gridclick == (2,4):
            cmd = "rotationplus"
        elif gridclick == (0,5):
            cmd = "flipvertical"
        elif gridclick == (1,5):
            cmd = "flipboth"
        elif gridclick == (2,5):
            cmd = "fliphorizontal"    
        elif gridclick == (0,6):
            cmd = "color0"
        elif gridclick == (1,6):
            cmd = "color1"
        elif gridclick == (2,6):
            cmd = "color2"
        elif gridclick == (0,7):
            cmd = "zoomarea"
        elif gridclick == (1,7):
            cmd = "fullscreen"
