def res_detect(webcam):
    v4l = shutil.which("v4l2-ctl")
    if not v4l == None:
        # get resolution information from video4linux
        res = subprocess.check_output(v4l+' -d /dev/video0 --list-formats-ext | grep Size | cut -d " " -f 3 | sort | uniq', shell=True).splitlines()
        for r in res:
            test = tuple( int(i) for i in r.decode().split("x"))
            resolutions.append(test)
            resolutions.sort(reverse=True)
    else:
        # testing common resolutions
        vs = imutils.video.WebcamVideoStream(src=0)  # threaded stream
        for x,y in test_res:
            works = False
            vs.stream.set(3, x)
            vs.stream.set(4, y)
            # test if SET resolutions are same as GET 
            if (int(vs.stream.get(3)) == x and int(vs.stream.get(4)) == y):
                works = True
            # another chance (worked for corvusalbus)
            elif (int(vs.stream.get(cv2.CAP_PROP_FRAME_WIDTH)) == x and int(vs.stream.get(cv2.CAP_PROP_FRAME_HEIGHT)) == y):
                works = True
            if works:
                resolutions.append((x,y))
        if len(resolutions) == 0:
            sys.exit('no valid resolutions')
        vs.stream.release()        
    return resolutions

def cam(src, r):
    # detect resolutions (as fast as possible)
    v = imutils.video.WebcamVideoStream(src=src)  # threaded stream
    #v    = cv2.VideoCapture(0)                             # unthreaded stream
    codec = 0x47504A4D  # MJPG
    v.stream.set(cv2.CAP_PROP_FPS, 30.0)
    v.stream.set(cv2.CAP_PROP_FOURCC, codec)
    #v.stream.set(cv2.CAP_PROP_FRAME_WIDTH, 1280)
    #v.stream.set(cv2.CAP_PROP_FRAME_HEIGHT, 720)
    v.stream.set(3, r[0])
    v.stream.set(4, r[1])
    v.start()
    b = np.uint8(np.absolute(blank_rgb * np.ones((r[1], r[0], 3), np.uint8)))
    return v, b


